// ponytail: la ficha JSON y la transaccion existentes conservan el registro comercial.
function posComPedido(id:string){const p=[...(window.pedidos||[]),...(window.pedidosFinalizados||[])].find(x=>String(x.id)===String(id));if(!p)throw Error('Pedido no encontrado.');return p;}
function posComCantidad(n:any){const q=Number(n);if(!Number.isSafeInteger(q)||q<1)throw Error('La cantidad debe ser un entero mayor a cero.');return q;}
function posComCentavos(n:any){const x=Number(n);if(!Number.isFinite(x)||x<0||x>100000000)throw Error('Importe inválido.');return Math.round(x*100);}
function posComVariante(p:any,key:string){if(!(p.variants||[]).length)return null;const v=p.variants.find((v:any)=>`${v.type||v.tipo||''}:${v.value||v.valor||''}`===String(key));if(!v)throw Error(`Elige una variante válida de ${p.name}.`);return v;}
function posComStock(items:any[],direction:number,reason:string){
 const plans=new Map<string,any>();
 for(const i of items){if(i.id==='libre')continue;const p=(window.products||[]).find(p=>String(p.id)===String(i.id));if(!p||['servicio','materia_prima','pack'].includes(p.tipo))throw Error('Selecciona piezas terminadas existentes.');const v=posComVariante(p,i.variante),key=JSON.stringify([p.id,i.variante||'']),q=posComCantidad(i.quantity||i.cantidad);const prior=plans.get(key);if(prior)prior.qty+=q;else plans.set(key,{p,v,qty:q});}
 if(!plans.size)throw Error('El pedido no contiene piezas terminadas.');
 for(const {p,v,qty} of plans.values()){const available=Number(v?v.qty:p.stock)||0;if(direction<0&&available<qty)throw Error(`Solo hay ${available} piezas terminadas de ${p.name}${v?' · '+(v.value||v.valor):''}.`);}
 for(const {p,v,qty} of plans.values()){const before=Number(v?v.qty:p.stock)||0,after=before+direction*qty;if(v){v.qty=after;p.stock=p.variants.reduce((s:number,v:any)=>s+(Number(v.qty)||0),0);}else p.stock=after;registrarMovimiento({productoId:p.id,productoNombre:p.name,tipo:direction>0?'entrada':'salida',cantidad:direction*qty,motivo:reason+(v?' · '+(v.value||v.valor):''),stockAntes:before,stockDespues:after});}
 return plans.size;
}
async function posComGuardarPedido(p:any){if((window.pedidos||[]).includes(p))await savePedidos();else await savePedidosFinalizados();}
async function posApartarPedido(id:string){
 return posRunOperation(async()=>{const p=posComPedido(id);if(!(window.pedidos||[]).includes(p)||['cancelado','finalizado','entregado'].includes(p.status))throw Error('Aparta desde un pedido activo.');if(p.inventarioDescontado)throw Error('Este pedido ya tiene el inventario descontado.');
 const items=JSON.parse(JSON.stringify((p.productosInventario||[]).filter((i:any)=>i.id!=='libre')));posComStock(items,-1,`Apartado ${p.folio}`);p.posDetalle={...p.posDetalle,apartado:{activo:true,modo:'terminado',fecha:new Date().toISOString(),items}};p.inventarioDescontado=true;await saveProducts();await posComGuardarPedido(p);},'Apartar piezas terminadas');
}
function posComRestaurarApartado(p:any){const a=p.posDetalle?.apartado;if(!a?.activo)return false;posComStock(a.items,1,`Liberación de apartado ${p.folio}`);a.activo=false;a.liberado=new Date().toISOString();return true;}
async function posLiberarApartado(id:string){return posRunOperation(async()=>{const p=posComPedido(id);if(!(window.pedidos||[]).includes(p)||!p.posDetalle?.apartado?.activo)throw Error('No hay un apartado activo.');posComRestaurarApartado(p);p.posDetalle.apartado.modo='liberado';p.inventarioDescontado=false;await saveProducts();await posComGuardarPedido(p);},'Liberar apartado');}
function posComApartadas(productId:string){return (window.pedidos||[]).filter(p=>!['cancelado','finalizado','entregado'].includes(p.status)&&p.posDetalle?.apartado?.activo).reduce((s:number,p:any)=>s+p.posDetalle.apartado.items.filter((i:any)=>String(i.id)===String(productId)).reduce((n:number,i:any)=>n+Number(i.quantity||i.cantidad||0),0),0);}
Object.assign(window,{posApartarPedido,posLiberarApartado,posComStock,posComRestaurarApartado,posComApartadas});

function posPromocionLineas(promo:any,products:any[]){
 const target=posComCentavos(promo.precio);if(!target||!String(promo.nombre||'').trim())throw Error('Escribe nombre y precio de la promoción.');
 const entries=(promo.items||[]).map((i:any)=>{const p=products.find(p=>String(p.id)===String(i.id));if(!p||['materia_prima','pack','servicio'].includes(p.tipo))throw Error('El componente de la promoción no está disponible.');posComVariante(p,i.variante);const qty=posComCantidad(i.quantity);const value=typeof window.pvGetPrecio==='function'&&p.tipo==='producto_variable'?window.pvGetPrecio(p,qty,i.variante):Number(p.price)||0;return {i,p,qty,weight:Math.max(1,posComCentavos(value))*qty};});
 if(entries.reduce((s:number,e:any)=>s+e.qty,0)<2)throw Error('Incluye al menos dos piezas en la promoción.');
 const weight=entries.reduce((s:number,e:any)=>s+e.weight,0),id=mkId(),out:any[]=[];let rest=target;
 entries.forEach((e:any,index:number)=>{const amount=index===entries.length-1?rest:Math.floor(target*e.weight/weight);rest-=amount;const unit=Math.floor(amount/e.qty),extra=amount%e.qty;const base={id:e.p.id,name:e.p.name,variante:e.i.variante||null,posPromocion:{id,nombre:String(promo.nombre).trim(),total:target/100}};if(e.qty>extra)out.push({...base,quantity:e.qty-extra,price:unit/100});if(extra)out.push({...base,quantity:extra,price:(unit+1)/100});});
 return out;
}
Object.assign(window,{posPromocionLineas});

function posComLineasVendidas(p:any){return [...(p.productosInventario||[]),...(p.posDetalle?.itemsCambio||[])];}
function posComDevolvible(p:any,index:number){const line=posComLineasVendidas(p)[index];if(!line)return 0;return Number(line.quantity||line.cantidad||1)-(p.posDetalle?.devoluciones||[]).filter((r:any)=>r.index===index).reduce((s:number,r:any)=>s+Number(r.quantity||0),0);}
function posComCobradoNeto(p:any){return Math.max(0,posTotalPagado(p)+(p.posDetalle?.devoluciones||[]).reduce((s:number,r:any)=>s+(Number(r.cobro)||0)-(Number(r.reembolso)||0),0));}
async function posRegistrarDevolucion(id:string,input:any){
 return posRunOperation(async()=>{
 const p=posComPedido(id);if(!(window.pedidosFinalizados||[]).includes(p)||!['finalizado','entregado','completado'].includes(p.status))throw Error('Selecciona un pedido vendido del historial.');
 if(input.before&&input.before!==JSON.stringify(p))throw Error('El pedido cambió. Vuelve a abrirlo.');
 const index=Number(input.index),quantity=posComCantidad(input.quantity);if(!Number.isSafeInteger(index)||quantity>posComDevolvible(p,index))throw Error('La cantidad supera las piezas pendientes de devolver.');
 const item=posComLineasVendidas(p)[index],reason=String(input.motivo||'').trim();if(!reason)throw Error('Escribe el motivo del cambio o devolución.');if(!['cash','transferencia','card'].includes(input.method))throw Error('Elige el método de devolución o cobro.');
 const original=posComCentavos(item.price)*quantity;
 let refund=posComCentavos(input.monto||0),charge=0,replacement:any=null;
 if(input.cambio){const prod=(window.products||[]).find(p=>String(p.id)===String(input.cambio.id));if(!prod)throw Error('Producto de cambio no encontrado.');posComVariante(prod,input.cambio.variante);const q=posComCantidad(input.cambio.quantity),price=posComCentavos(input.cambio.price);replacement={id:prod.id,name:prod.name,variante:input.cambio.variante||null,quantity:q,price:price/100};const delta=price*q-original;refund=Math.max(0,-delta);charge=Math.max(0,delta);}
 if(refund>Math.min(original,posComCentavos(posComCobradoNeto(p))))throw Error('El reembolso supera el valor devuelto o el dinero cobrado disponible.');
 // Validar la salida antes de devolver piezas: la transaccion tambien revierte fallos posteriores.
 if(replacement){const prod=window.products.find(p=>String(p.id)===String(replacement.id)),v=posComVariante(prod,replacement.variante);const recovery=input.recuperar&&String(item.id)===String(replacement.id)&&String(item.variante||'')===String(replacement.variante||'')?quantity:0;if((Number(v?v.qty:prod.stock)||0)+recovery<replacement.quantity)throw Error('No hay piezas terminadas suficientes para el cambio.');}
 if(input.recuperar&&item.id!=='libre')posComStock([{...item,quantity}],1,`Devolución ${p.folio}: ${reason}`);
 if(replacement)posComStock([replacement],-1,`Cambio ${p.folio}: ${reason}`);
 const entry={id:mkId(),fecha:new Date().toISOString(),index,quantity,recuperar:!!input.recuperar,motivo:reason,reembolso:refund/100,cobro:charge/100,method:input.method,cambio:replacement};
 p.posDetalle={...p.posDetalle,devoluciones:[...(p.posDetalle?.devoluciones||[]),entry],itemsCambio:[...(p.posDetalle?.itemsCambio||[]),...(replacement?[replacement]:[])]};
 const cash={id:entry.id,date:posComHoy(),concept:`${refund?'Devolución':'Diferencia de cambio'} ${p.folio} · ${reason}`,amount:(refund||charge)/100,method:input.method,category:'Cambios y devoluciones',etiqueta:'Cambios y devoluciones',client:p.cliente};
 if(refund){window.expenses.push(cash);await saveExpenses();}if(charge){window.incomes.push(cash);await saveIncomes();}
 await saveProducts();await posComGuardarPedido(p);return entry;
 },'Registrar cambio o devolución');
}
function posComPuedeReescribir(p:any){if(p?.posDetalle?.devoluciones?.length){manekiToastExport('Este pedido tiene cambios o devoluciones registrados. Consúltalos desde su ficha comercial; conserva la venta original.','warn');return false;}return true;}
Object.assign(window,{posRegistrarDevolucion,posComLineasVendidas,posComDevolvible,posComCobradoNeto,posComPuedeReescribir});

function posComHoy(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function posComFecha(s:string){if(!/^\d{4}-\d{2}-\d{2}$/.test(s))throw Error('Fecha inválida.');const d=new Date(s+'T12:00:00Z');if(!Number.isFinite(d.getTime())||d.toISOString().slice(0,10)!==s)throw Error('Fecha inválida.');return d;}
function posCapacidadDias(orders:any[],start:string,days=30,limite=0){
 const date=posComFecha(start);if(!Number.isSafeInteger(days)||days<1||days>90)throw Error('Elige de 1 a 90 días.');if(!Number.isSafeInteger(limite)||limite<0)throw Error('Capacidad inválida.');
 return Array.from({length:days},(_,index)=>{const d=new Date(date.getTime()+index*86400000),fecha=d.toISOString().slice(0,10);const list=orders.filter(p=>p.entrega===fecha&&['confirmado','pago','produccion'].includes(p.status)&&!p.posDetalle?.apartado?.activo);const piezas=list.reduce((sum,p)=>sum+(p.productosInventario||[]).filter((i:any)=>i.id!=='libre').reduce((s:number,i:any)=>s+(Number(i.quantity||i.cantidad)||0),0),0);return {fecha,piezas,pedidos:list.length,limite,exceso:limite?Math.max(0,piezas-limite):0,folios:list.map(p=>p.folio||p.cliente).join(', ')};});
}
Object.assign(window,{posCapacidadDias});

async function posRegistrarTiempo(id:string,input:any){return posRunOperation(async()=>{const p=posComPedido(id),minutos=Number(input.minutos),actividad=String(input.actividad||'').trim();if(!Number.isSafeInteger(minutos)||minutos<1||minutos>1440)throw Error('Registra de 1 a 1440 minutos por sesión.');if(!actividad)throw Error('Escribe la actividad realizada.');posComFecha(input.fecha);if(input.before&&input.before!==JSON.stringify(p))throw Error('El pedido cambió. Vuelve a abrirlo.');p.posDetalle={...p.posDetalle,tiempos:[...(p.posDetalle?.tiempos||[]),{id:mkId(),fecha:input.fecha,minutos,actividad}]};await posComGuardarPedido(p);},'Registrar tiempo de producción');}
function posTiempoResumen(p:any){const minutos=(p.posDetalle?.tiempos||[]).reduce((s:number,t:any)=>s+(Number(t.minutos)||0),0),ajuste=(p.posDetalle?.devoluciones||[]).reduce((s:number,r:any)=>s+Number(r.cobro||0)-Number(r.reembolso||0),0);const profit=window.posRentabilidad?.({...p,total:Number(p.total||0)+ajuste},p.posDetalle?.costos||{});return {minutos,gananciaHora:minutos&&profit?.ganancia!=null?Math.round(profit.ganancia*60/minutos*100)/100:null};}
function posPersonalizacionLinea(nombre:string,precio:any,cantidad:any){const name=String(nombre||'').trim();if(!name)throw Error('Describe la personalización.');const cents=posComCentavos(precio),qty=posComCantidad(cantidad);if(!cents)throw Error('Escribe el precio del extra.');return {id:'libre',name:`Personalización · ${name}`,quantity:qty,price:cents/100,variante:null,posPersonalizacion:true};}
