function posComProductosOptions(){return (window.products||[]).filter(p=>!['materia_prima','servicio','pack'].includes(p.tipo)&&p.activo!==false).flatMap(p=>(p.variants?.length?p.variants:[null]).map(v=>`<option value="${_esc(JSON.stringify([String(p.id),v?`${v.type||v.tipo}:${v.value||v.valor}`:null]))}">${_esc(p.name)}${v?' · '+_esc(v.value||v.valor):''}</option>`)).join('');}
