 const orders=[...(window.pedidos||[]),...(window.pedidosFinalizados||[])];const p=id?posComPedido(id):orders[0];const d=posDialog('Apartados, cambios y tiempo');d.classList.add('pos-commerce-dialog');if(!p){d.append('Crea un pedido para usar estas herramientas.');return;}
